#!/usr/bin/env node
// Generates src/theme.css and src/fonts.css from src/tokens.ts. Do not edit those files by hand.
import { writeFileSync } from 'node:fs';
import { breakpoints, colors, font, gutter, radii } from '../src/tokens.ts';

export function themeCss() {
  const lines = [
    '/* GENERATED by scripts/build-theme.mjs from src/tokens.ts. Do not edit. */',
    '/* Use with Tailwind 4: @import "tailwindcss"; @import "@zurichjs/design/theme.css"; */',
    '',
    '@theme {',
    '  --breakpoint-*: initial;',
    ...Object.entries(breakpoints).map(([k, v]) => `  --breakpoint-${k}: ${v};`),
    '',
    ...Object.entries(colors).map(([k, v]) => `  --color-${k}: ${v};`),
    '',
    `  --font-sans: var(${font.cssVariable}, '${font.family}'), ${font.fallbacks.join(', ')};`,
    '',
    ...Object.entries(radii).map(([k, v]) => `  --radius-${k}: ${v};`),
    '',
    `  --container-site: ${gutter.column};`,
    '}',
    '',
    '@utility px-gut {',
    '  padding-left: var(--gut);',
    '  padding-right: var(--gut);',
    '}',
    '',
    '@utility mx-gut {',
    '  margin-left: var(--gut);',
    '  margin-right: var(--gut);',
    '}',
    '',
    '@layer base {',
    '  :root {',
    `    --px: ${gutter.mobile};`,
    `    --gut: max(var(--px), calc((100% - ${gutter.column}) / 2));`,
    '  }',
    `  @media (min-width: ${breakpoints.md}) {`,
    '    :root {',
    `      --px: ${gutter.desktop};`,
    '    }',
    '  }',
    '  html {',
    '    -webkit-font-smoothing: antialiased;',
    '    font-synthesis: none;',
    '    scroll-behavior: smooth;',
    '  }',
    '  @media (prefers-reduced-motion: reduce) {',
    '    html {',
    '      scroll-behavior: auto;',
    '    }',
    '    *,',
    '    *::before,',
    '    *::after {',
    '      transition: none !important;',
    '      animation: none !important;',
    '    }',
    '  }',
    '  body {',
    '    margin: 0;',
    `    background: ${colors.white};`,
    `    color: ${colors.black};`,
    '    font-family: var(--font-sans);',
    '  }',
    '  ::placeholder {',
    `    color: ${colors['grey-placeholder']};`,
    '    opacity: 1;',
    '  }',
    '  a {',
    '    color: inherit;',
    '    text-underline-offset: 3px;',
    '  }',
    '  :focus-visible {',
    `    outline: 3px solid ${colors.blue};`,
    '    outline-offset: 2px;',
    '  }',
    '  /* Yellow focus ring on black surfaces, where blue would disappear. */',
    '  .on-black :focus-visible {',
    `    outline-color: ${colors.yellow};`,
    '  }',
    '}',
    '',
  ];
  return lines.join('\n');
}

/** @font-face for sites that do not use the Astro Fonts API (e.g. the conference site). */
export function fontsCss() {
  return [
    '/* GENERATED by scripts/build-theme.mjs from src/tokens.ts. Do not edit. */',
    '@font-face {',
    `  font-family: '${font.family}';`,
    `  src: url('./fonts/${font.file}') format('woff2');`,
    `  font-weight: ${font.weights};`,
    '  font-style: normal;',
    '  font-display: swap;',
    '}',
    `:root {`,
    `  ${font.cssVariable}: '${font.family}';`,
    '}',
    '',
  ].join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const dir = new URL('../src/', import.meta.url);
  writeFileSync(new URL('theme.css', dir), themeCss());
  writeFileSync(new URL('fonts.css', dir), fontsCss());
  console.log('wrote src/theme.css and src/fonts.css');
}
